import React from "react";
import SubHeading from "../../../Components/Heading/SubHeading";
import muc from "./"

function Section4() {
  let obj = [
    {
      planet: "Mercury",
      para:
        "The Smallest Planet in the Solar System" +
        "Mercury, the innermost planet in the solar system, is the smallest and closest planet to the Sun. With a diameter of about 4,880 kilometers, it is only slightly larger than Earth's Moon. Mercury's proximity to the Sun makes it challenging to observe from Earth, but it is a fascinating world with unique characteristics. The planet has no atmosphere to moderate temperatures, resulting in extreme fluctuations: daytime temperatures can soar to 430°C (800°F), while nighttime temperatures plummet to -180°C (-290°F). This dramatic contrast highlights its harsh and inhospitable environment." +
        "Unlike Earth, Mercury has a heavily cratered surface that reflects its long history of bombardment by meteoroids and comets. Its largest impact feature, the Caloris Basin, spans about 1,550 kilometers and is surrounded by rings of mountains. Mercury also has large, smooth plains and cliffs called scarps that stretch hundreds of kilometers, formed as the planet cooled and contracted. These features reveal a geologically active past despite its small size and lack of significant volcanic or tectonic activity today." +
        "Mercury has a weak magnetic field, about 1% as strong as Earth's, which suggests it has a partially molten iron core. This core occupies about 85% of the planet's radius, making Mercury the most metal-rich planet in the solar system by proportion. Scientists believe its large core is a result of its formation, where it lost much of its original rocky material due to a giant impact or intense solar radiation. This composition gives Mercury an extremely high density, second only to Earth in the solar system." +
        "A single day on Mercury (a full rotation on its axis) lasts 59 Earth days, while its year (one complete orbit around the Sun) takes only 88 Earth days. This unusual relationship between its rotational and orbital periods results in a phenomenon where one Mercurian day lasts two Mercurian years. Standing on its surface, an observer would see the Sun rise, pause, reverse direction briefly, and then resume its path across the sky." +
        "Space exploration has provided much of what we know about Mercury. NASA's MESSENGER mission, which orbited Mercury from 2011 to 2015, mapped its surface and analyzed its composition, atmosphere, and magnetic field. Currently, the joint European-Japanese mission **BepiColombo** is en route to Mercury and is expected to arrive in 2025, promising even more insights into this enigmatic planet. Mercury remains a testament to the dynamic and varied nature of the solar system's smallest and closest planet to the Sun.",
    },
  ];

  const solarSystemPlanets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <div className=" w-full h-screen ">
      <SubHeading text="Solar System Planets" />
      <div className=""></div>
    </div>
  );
}

export default Section4;
